import math

from fastapi import FastAPI, Query

app = FastAPI()

# 137 generated in-memory items
ITEMS = [{"id": i, "name": f"item-{i}"} for i in range(1, 138)]


@app.get("/items")
def list_items(
    page: int = Query(default=1, ge=1),
    per_page: int = Query(default=20, gt=0, le=100),
):
    start = (page - 1) * per_page
    data = ITEMS[start : start + per_page]
    return {
        "data": data,
        "meta": {
            "total": len(ITEMS),
            "page": page,
            "per_page": per_page,
            "total_pages": math.ceil(len(ITEMS) / per_page),
        },
    }

